/// <summary>
/// AVADAI Module global class
/// </summary>
class AVADAIGlobal
{
}

Method.Source:
/// <summary>
/// return value as string
/// </summary>
/// <param name = "_value">AnyType</param>
/// <param name = "_types">Types</param>
/// <param name = "_extendedTypeId">ExtendedTypeId</param>
/// <returns>str</returns>
public static str anyToStr(AnyType _value, Types _types = typeOf(_value), ExtendedTypeId _extendedTypeId = 0, EnumId     _enumId = 0)
{
    str     strValue;
    int     decimals;

    switch (typeof(_value))
    {
        case Types::Real:
            decimals = AxdBaseRead::getNoOfDecimals(_types, _extendedTypeId);
            strValue = AVADAIGlobal::real2StrGlobal(_value, decimals);
            break;
        case Types::Date:
            strValue = AVADAIGlobal::date2StrGlobal(_value);
            break;
        case Types::UtcDateTime:
            strValue = AVADAIGlobal::dateTime2StrGlobal(_value);
            break;

        case Types::Enum:
            if (_enumId == enumNum(NoYes))
            {
                strValue = AVADAIGlobal::noYes2StrGlobal(_value);
            }
            else
            {
                strValue =  strFmt('%1', _value);
            }
            break;

        default:
            strValue =  strFmt('%1', _value);
    }

    return strValue;
}

/// <summary>
/// return real as string with defines format
/// </summary>
/// <param name = "_number">real</param>
/// <param name = "_decimals">int</param>
/// <returns>str</returns>
public static str real2StrGlobal(real _number, int _decimals)
{
    str                 tmpStr;
    AVADAIServer        dmsServer;

    dmsServer = AVADAIServer::findServer(AVADAIParameters::find().ServerId);

    if (dmsServer)
    {
        if (dmsServer.DecimalSeparator == DecimalSeparator::Auto)
        {
            tmpStr = strFmt('%1', _number);
        }
        else
        {
            tmpStr = num2Str(_number,1,_decimals,dmsServer.DecimalSeparator,ThousandSeparator::None);
        }
    }
    else
    {
        tmpStr = strFmt('%1', _number);
    }

    return tmpStr;
}

/// <summary>
/// return date as string with defines format
/// </summary>
/// <param name = "_date">date</param>
/// <returns>str</returns>
public static str date2StrGlobal(date _date)
{
    str             tmpStr;
    AVADAIServer    dmsServer;

    dmsServer = AVADAIServer::findServer(AVADAIParameters::find().ServerId);
    if (dmsServer && _date && dmsServer.DateFormat != '')
    {
        tmpStr = System.String::Format(strFmt('{0:%1}', dmsServer.DateFormat), _date);
    }
    else
    {
        tmpStr = strFmt('%1', _date);
    }

    return tmpStr;
}

/// <summary>
/// return date time as string with defines format
/// </summary>
/// <param name = "_dateTime">utcdatetime</param>
/// <returns>str</returns>
public static str dateTime2StrGlobal(utcdatetime _dateTime)
{
    str                 tmpStr;
    AVADAIServer        dmsServer;
    System.DateTime     systemDateTime;
    dmsServer           = AVADAIServer::findServer(AVADAIParameters::find().ServerId);

    if (dmsServer && _dateTime && dmsServer.DateTimeFormat != '')
    {
        systemDateTime  = Global::utcDateTime2SystemDateTime(_dateTime);
        tmpStr          = System.String::Format(strFmt('{0:%1}', dmsServer.DateTimeFormat), systemDateTime);
    }
    else
    {
        tmpStr = strFmt('%1', _dateTime);
    }

    return tmpStr;
}

/// <summary>
/// Set form configuration.
/// </summary>
/// <param name = "Boolean">Tboolean value</param>
/// <returns>A <c>string</c> Returns in which boolean format it is in (either yes or no).</returns>
public static str noYes2StrGlobal(NoYes     _noYes)
{
    str                 tmpStr;
    AVADAIServer        AVADAIServer = AVADAIServer::findServer(AVADAIParameters::find().ServerId);

    switch (AVADAIServer.BooleanFormat)
    {
        case AVADAIBooleanFormat::NoYes :
            tmpStr = (_noYes == NoYes::Yes) ? 'Yes' : 'No';
            break;

        case AVADAIBooleanFormat::NullOne :
            tmpStr = (_noYes == NoYes::Yes) ? '1' : '0';
            break;

        case AVADAIBooleanFormat::TrueFalse :
            tmpStr = (_noYes == NoYes::Yes) ? 'true' : 'false';
            break;

        default :
            tmpStr = enum2Str(_noYes);
            break;
    }

    return tmpStr;
}
